using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
[Serializable] public class PartUnit {
 public string id,modelId,calibrationId,slot,choice,offerId,sourceEngineId,sourceCarId,owner,status,installedEngineId,createdTransactionId,lastTransactionId;
 public int stage;
}
[Serializable] public class ComponentMove {
 public int rules=1,fee,stage;
 public string carId,engineId,partId,modelId,calibrationId,slot,choice,offerId;
}
// Only genuinely fitted assemblies become loose parts, through a paid removal receipt.
// Legacy shop history does not manufacture spares that the player never removed.
public static class ComponentInventoryLedger {
 static void Need(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 public static bool IsReceipt(TuneReceipt r)=>r.kind=="component_remove"||r.kind=="component_fit";
 public static bool Supports(string slot)=>slot=="induction"||slot=="cooling"||slot=="intake"||slot=="exhaust";
 public static int Labor(string slot)=>slot=="induction"?250:slot=="cooling"?100:slot=="intake"?75:slot=="exhaust"?100:throw new InvalidOperationException("Only bolt-on induction, cooling, intake and exhaust packages can be removed");
 public static string Calibration(string model)=>model+":matched_workshop_v1";
 public static int Stage(WorkshopBuild b,string slot)=>slot=="induction"?b.inductionStage:slot=="cooling"?b.coolingStage:slot=="intake"?b.intakeStage:slot=="exhaust"?b.exhaustStage:throw new InvalidOperationException("Unsupported component slot");
 public static string Choice(WorkshopBuild b,string slot)=>slot=="induction"?b.induction:slot;
 public static string Offer(string slot,string choice,int stage)=>slot=="induction"?"induction_"+choice+"_"+stage:slot+"_"+stage;
 public static PartUnit Find(FleetState f,string id)=>f.parts?.SingleOrDefault(p=>p.id==id)??throw new InvalidOperationException("Unknown component identity");
 public static void ValidateLegacy(FleetState f){if(f==null)return;Need(!f.partsReady&&(f.parts==null||f.parts.Count==0),"Legacy fleet contains unsupported loose-component history");f.parts=new List<PartUnit>();}
 public static void Ensure(FleetState f){EngineInventoryLedger.Ensure(f);if(f.partsReady)return;Need(f.parts==null||f.parts.Count==0,"Uninitialized component inventory already has items");f.parts=new List<PartUnit>();f.partsReady=true;}
 public static FleetCar OwnedCar(FleetState f,string carId){Need(carId!=FleetLedger.Loaner,"Recovery loaner hardware cannot be removed or changed");Need(!f.HasPending,"Finish the committed race before component work");var car=FleetLedger.Find(f,carId);Need(car.owner=="player","Only your owned car can supply or receive components");Need(EngineInventoryLedger.HasEngine(f,carId),"Install an engine before working on its bolt-on hardware");return car;}
 public static EngineUnit Engine(FleetState f,FleetCar car)=>EngineInventoryLedger.Find(f,car.engineId);
 static void Set(WorkshopBuild b,string slot,string choice,int stage){switch(slot){case "induction":b.induction=stage==0?"none":choice;b.inductionStage=stage;break;case "cooling":b.coolingStage=stage;break;case "intake":b.intakeStage=stage;break;case "exhaust":b.exhaustStage=stage;break;default:throw new InvalidOperationException("Unsupported component slot");}}
 // A purchased Stage3 complete package contains its earlier incremental stages.
 // Its external supporting hardware and tune still have to exist on the receiver.
 static void Requirements(WorkshopCatalog catalog,WorkshopBuild build,WorkshopOffer offer,HashSet<string> seen){if(!seen.Add(offer.id))return;if(offer.apexOnly&&catalog.car.carId!="car_apex_test")throw new InvalidOperationException("This engine/frame has no matched Apex twin-turbo mounting kit");foreach(string id in offer.prerequisites??Array.Empty<string>()){var previous=catalog.Find(id);Need(catalog.Installed(build,previous),"Requires "+previous.name+"; existing paid supporting hardware was not removed");Requirements(catalog,build,previous,seen);}}
 static void SupportedBuild(WorkshopCatalog catalog,WorkshopBuild build){var seen=new HashSet<string>();if(build.naStage>0)Requirements(catalog,build,catalog.Find("na_"+build.naStage),seen);if(build.induction!="none"&&build.inductionStage>0)Requirements(catalog,build,catalog.Find(Offer("induction",build.induction,build.inductionStage)),seen);foreach(string slot in new[]{"cooling","intake","exhaust"}){int stage=Stage(build,slot);if(stage>0)Requirements(catalog,build,catalog.Find(Offer(slot,slot,stage)),seen);}if(build.sound!="road")Requirements(catalog,build,catalog.Find("sound_"+build.sound+"_"+build.soundStage),seen);catalog.Resolve(build);}
 static void CheckRemoval(FleetState f,FleetCar car,string slot){Need(Supports(slot),"That component cannot be removed separately");int stage=Stage(car.build,slot);Need(stage>0&&(slot!="induction"||car.build.induction!="none"),slot=="induction"?"No removable aftermarket induction kit is fitted; an integral factory turbo engine is not a loose bolt-on kit":"No upgraded "+slot+" component is fitted");var catalog=WorkshopCatalog.ForBuild(VehicleLineup.Model(car),car.build);var simulation=catalog.Copy(car.build);Set(simulation,slot,Choice(car.build,slot),0);try{SupportedBuild(catalog,simulation);}catch(Exception e){throw new InvalidOperationException("Cannot remove "+slot+" while the remaining calibration requires it. Remove dependent induction / choose a compatible sound tune first. "+e.Message,e);}}
 public static int RemovalFee(FleetState f,string carId,string slot){Ensure(f);var car=OwnedCar(f,carId);CheckRemoval(f,car,slot);return Labor(slot);}
 static void CheckFit(FleetState f,PartUnit part,FleetCar car){var engine=Engine(f,car);Need(part.owner=="player"&&part.status=="stored"&&string.IsNullOrEmpty(part.installedEngineId),"Remove this component into your inventory before fitting it");Need(part.modelId==engine.modelId&&part.calibrationId==Calibration(engine.modelId),"Component has no matched mounting/calibration for this engine model");Need(Stage(car.build,part.slot)==0&&(part.slot!="induction"||car.build.induction=="none"),"The receiver already has this component slot fitted; remove it first");var catalog=WorkshopCatalog.ForBuild(VehicleLineup.Model(car),car.build);var offer=catalog.Find(part.offerId);Need(offer.slot==part.slot&&offer.choice==part.choice&&offer.stage==part.stage,"Stored component no longer matches a supported kit definition");Need(!(part.slot=="induction"&&catalog.car.stock.IsTurbo),"This factory-turbo package does not accept replacement bolt-on induction kits");var simulation=catalog.Copy(car.build);Set(simulation,part.slot,part.choice,part.stage);SupportedBuild(catalog,simulation);}
 public static int FitFee(FleetState f,string partId,string carId){Ensure(f);var car=OwnedCar(f,carId);var part=Find(f,partId);CheckFit(f,part,car);return Labor(part.slot);}
 public static void SyncOwners(FleetState f){if(!f.partsReady)return;foreach(var part in f.parts)if(part.status=="installed")part.owner=EngineInventoryLedger.Find(f,part.installedEngineId).owner;}
 public static void AfterWorkshop(FleetState f,FleetCar car,WorkshopOffer offer,string transaction){if(!f.partsReady||!Supports(offer.slot))return;var part=f.parts.SingleOrDefault(p=>p.status=="installed"&&p.installedEngineId==car.engineId&&p.slot==offer.slot);if(part==null)return;int stage=Stage(car.build,offer.slot);string choice=Choice(car.build,offer.slot);if(stage>=part.stage&&choice==part.choice){part.stage=stage;part.offerId=Offer(part.slot,choice,stage);part.lastTransactionId=transaction;}else{part.status="consumed";part.installedEngineId="";part.lastTransactionId=transaction;}}
 public static void Replay(FleetState f,TuneReceipt r,string profileId){Ensure(f);Need(r.pathId=="components_v10"&&r.stage==0&&r.credits>0,"Invalid paid component transaction");var move=JsonUtility.FromJson<ComponentMove>(r.fleetJson);Need(move!=null&&move.rules==1&&move.fee==r.credits&&r.configId==move.carId&&r.partId==move.partId&&Supports(move.slot),"Component transaction payload changed");var car=OwnedCar(f,move.carId);var engine=Engine(f,car);Need(engine.id==move.engineId&&engine.modelId==move.modelId&&move.calibrationId==Calibration(engine.modelId),"Component transaction engine or calibration changed");if(r.kind=="component_remove"){CheckRemoval(f,car,move.slot);Need(Stage(car.build,move.slot)==move.stage&&Choice(car.build,move.slot)==move.choice&&move.offerId==Offer(move.slot,move.choice,move.stage),"Removal does not match genuinely fitted component");var part=f.parts.SingleOrDefault(p=>p.status=="installed"&&p.installedEngineId==engine.id&&p.slot==move.slot);if(part==null){Need(move.partId==profileId+":component:"+r.transactionId&&!f.parts.Any(p=>p.id==move.partId),"Component identity was already used");part=new PartUnit{id=move.partId,modelId=engine.modelId,calibrationId=move.calibrationId,slot=move.slot,choice=move.choice,offerId=move.offerId,stage=move.stage,sourceEngineId=engine.id,sourceCarId=car.id,owner="player",createdTransactionId=r.transactionId};f.parts.Add(part);}else Need(part.id==move.partId&&part.stage==move.stage&&part.choice==move.choice,"Fitted component identity changed");Set(car.build,move.slot,move.choice,0);part.status="stored";part.installedEngineId="";part.lastTransactionId=r.transactionId;EngineInventoryLedger.Sync(f,car);return;}Need(r.kind=="component_fit","Unsupported component transaction");var stored=Find(f,move.partId);Need(stored.slot==move.slot&&stored.choice==move.choice&&stored.stage==move.stage&&stored.offerId==move.offerId,"Stored part specification changed");CheckFit(f,stored,car);Set(car.build,stored.slot,stored.choice,stored.stage);stored.status="installed";stored.installedEngineId=engine.id;stored.owner=engine.owner;stored.lastTransactionId=r.transactionId;EngineInventoryLedger.Sync(f,car);}
 public static void Validate(FleetState f){Need(f.partsReady&&f.parts!=null,"Component inventory was not initialized");var ids=new HashSet<string>();var slots=new HashSet<string>();foreach(var p in f.parts){Need(p!=null&&!string.IsNullOrEmpty(p.id)&&ids.Add(p.id)&&Supports(p.slot)&&p.stage>0&&p.calibrationId==Calibration(p.modelId)&&!string.IsNullOrEmpty(p.sourceEngineId)&&!string.IsNullOrEmpty(p.createdTransactionId)&&(p.owner=="player"||p.owner=="rival"),"Invalid component identity/provenance");var original=EngineInventoryLedger.Find(f,p.sourceEngineId);Need(original.modelId==p.modelId,"Component provenance model changed");var offer=WorkshopCatalog.Load(p.modelId).Find(p.offerId);Need(offer.slot==p.slot&&offer.choice==p.choice&&offer.stage==p.stage,"Invalid stored kit definition");if(p.status=="installed"){var e=EngineInventoryLedger.Find(f,p.installedEngineId);Need(slots.Add(e.id+":"+p.slot)&&e.modelId==p.modelId&&e.owner==p.owner&&Stage(e.build,p.slot)==p.stage&&Choice(e.build,p.slot)==p.choice,"Installed part disagrees with engine/owner/build");}else Need((p.status=="stored"||p.status=="consumed")&&string.IsNullOrEmpty(p.installedEngineId)&&p.owner=="player","Invalid loose/replaced component state");}}
}
}
